SELECT id, asset_type, filename, content_type, expected_size, expected_sha256,
       storage_key, idempotency_key, status, expires_at, created_at, media_asset_id
  FROM media_upload_sessions
 WHERE account_id = #{accountId}
   AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE media_upload_sessions
   SET status = 'VALIDATING', media_asset_id = #{mediaAssetId,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
 WHERE id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND account_id = #{accountId}
   AND status = 'PENDING_UPLOAD'

UPDATE media_upload_sessions
   SET status = 'REJECTED'
 WHERE id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND account_id = #{accountId}
   AND status = 'PENDING_UPLOAD'

UPDATE media_upload_sessions
   SET status = 'READY', media_asset_id = #{mediaAssetId,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
 WHERE id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND account_id = #{accountId}
   AND status IN ('PENDING_UPLOAD', 'VALIDATING')
